func ValidateNewContextName(name string) error {
	if err := ValidateContextName(name); err != nil {
		return err
	}
	for _, r := range reservedContextNames {
		if name == r {
			return fmt.Errorf("%q is reserved — choose another name: %w", name, ErrReservedContextName)
		}
	}
	return nil
}

